const body = $json.body || $json;

const temaPrincipal = (body.tema || body.title || body.assunto || 'Inovação e Vendas Digitais').trim();
const textoBase = (body.conteudo || body.content || body.texto || 'Dicas práticas para escalar sua operação sem aumentar custos de equipe.').trim();
const urlDestino = (body.url || body.link || 'https://minhaloja.com.br/artigo').trim();

return [{
  json: {
    tema_principal: temaPrincipal,
    texto_base: textoBase,
    url_destino: urlDestino
  }
}];

