// ===============================================================================
// DAEMIND SRE - PARSER DE CONTEÚDO ESTRUTURADO
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    post_social_media: $('Sanitizar Dados da Pauta').item.json.texto_base,
    newsletter_assunto: $('Sanitizar Dados da Pauta').item.json.tema_principal,
    newsletter_html: `<p>${$('Sanitizar Dados da Pauta').item.json.texto_base}</p>`
  };
}

return [{
  json: {
    ...parsed,
    tema: $('Sanitizar Dados da Pauta').item.json.tema_principal,
    url_destino: $('Sanitizar Dados da Pauta').item.json.url_destino
  }
}];

